file.content:
{%- if data.isWindow -%}
[window]
width = 220
height = 75
styleFile = "style.css"
opacity = 1
{% endif %}

{%- if data.isWidget -%}
[widget]
styleFile = "style.css"
{% endif %}

from .{{ pluginName | camelCase }} import {{ pluginName }}

{% if data.isWindow -%}
def createWindow(parent):
    return {{ pluginName }}(parent)
{% endif %}

{% if data.isWidget -%}
def createWidget(parent):
    return {{ pluginName }}(parent)
{% endif %}
